#!/bin/sh
# Fetch the images of docker-compose.yaml by digest into images/ (generated by hydo compose; hydo-build
# never pulls). Needs hydo-fetch-image (it comes with hydo) and network access, once.
# It fetches the images this machine builds: x86_64 on Linux, arm64 on a Mac. Name
# x86_64, arm64 or all as the argument to choose (sh fetch-images.sh all).
set -eu
cd "$(dirname "$0")"
A=${1:-}
[ -n "$A" ] || case "$(uname -s)" in Darwin) A=arm64;; *) A=x86_64;; esac
case "$A" in x86_64|arm64|all) ;; *) echo "fetch-images.sh: x86_64, arm64 or all (got $A)" >&2; exit 2;; esac
F=${HYDO_FETCH_IMAGE:-$(command -v hydo-fetch-image || true)}
[ -n "$F" ] || { echo "fetch-images.sh: hydo-fetch-image not found (put hydo's bin directory on PATH, or set HYDO_FETCH_IMAGE)" >&2; exit 1; }
mkdir -p images
[ "$A" = x86_64 ] || [ -e images/docker.gitea.com-gitea-28.4.0-rootless-arm64-oci ] || "$F" docker.gitea.com/gitea sha256:49d23f30d87bda56381cd6d37798764c5fced57b9ae004f1f231b00e6b4fb185 docker.gitea.com/gitea:28.4.0-rootless images/docker.gitea.com-gitea-28.4.0-rootless-arm64-oci
[ "$A" = arm64 ] || [ -f images/docker.gitea.com-gitea-28.4.0-rootless-amd64.docker.tar ] || "$F" docker.gitea.com/gitea sha256:0a28ed70ce0509217a48ce8da8d1ed1c8fcabdb54918b5d55540cfc6352a2d12 docker.gitea.com/gitea:28.4.0-rootless images/docker.gitea.com-gitea-28.4.0-rootless-amd64.docker.tar
[ "$A" = arm64 ] || ls -ld images/docker.gitea.com-gitea-28.4.0-rootless-amd64.docker.tar
[ "$A" = x86_64 ] || ls -ld images/docker.gitea.com-gitea-28.4.0-rootless-arm64-oci
